cypress_script:
describe('Bank Login and Navigation', () => {
  it('should log in successfully with valid credentials', () => {
    cy.visit('https://parabank.parasoft.com/parabank/index.htm');
    cy.get('input[name="username"]').type('validUsername');
    cy.get('input[name="password"]').type('validPassword');
    cy.get('input[type="submit"]').click();
    cy.url().should('not.include', 'index.htm');
  });
  it('should show an error message with invalid credentials', () => {
    cy.visit('https://parabank.parasoft.com/parabank/index.htm');
    cy.get('input[name="username"]').type('invalidUsername');
    cy.get('input[name="password"]').type('invalidPassword');
    cy.get('input[type="submit"]').click();
    cy.get('a').contains('Forgot login info?').should('be.visible');
  });
});

playwright_script:
import { test } from '@playwright/test';

test.describe('Bank Login and Navigation', () => {
  test('should log in successfully with valid credentials', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/index.htm');
    await page.fill('input[name="username"]', 'validUsername');
    await page.fill('input[name="password"]', 'validPassword');
    await page.click('input[type="submit"]');
    await page.waitForURL('**/*');
  });
  test('should show an error message with invalid credentials', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/index.htm');
    await page.fill('input[name="username"]', 'invalidUsername');
    await page.fill('input[name="password"]', 'invalidPassword');
    await page.click('input[type="submit"]');
    await page.locator('a').withText('Forgot login info?').isVisible();
  });
});
